using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1WildApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");static string Src=>Root+"/SourceAssets/F1_WildernessDetail/";static string Out=>Root+"/Docs/Review/2026-11-13_1F_WildernessDetail/";static Dictionary<string,GameObject> models=new Dictionary<string,GameObject>();static List<object> changes=new List<object>();static Terrain near,mid;
 static void Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");}
 static void Record(UnityEngine.Object o){if(PrefabUtility.IsPartOfPrefabInstance(o))PrefabUtility.RecordPrefabInstancePropertyModifications(o);}
 static float S(float a,float b,float x)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));
 public static float RoadZ(float x)=>-28-.035f*(-51-x)+Mathf.Sin((x+192)*.006f)*6*S(0,100,-x-192);
 static float Height(float x,float z){var t=x>=-192&&x<=192&&z>=-160&&z<=160?near:mid;return t.SampleHeight(new Vector3(x,0,z))+t.transform.position.y;}
 static void Materials(){foreach(string file in new[]{"WDNaturalLit.shader","WDNaturalForward.hlsl","WDNaturalGBuffer.hlsl","WDNaturalSurface.hlsl"})File.Copy(Src+file,E+file,true);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"WDNaturalLit.shader");if(ShaderUtil.GetShaderMessages(shader).Any(m=>m.severity.ToString()=="Error"))throw new Exception("Natural surface shader error");
 foreach(var q in new[]{new{name="Stone",color=new Color(.50f,.47f,.40f),mode=10f},new{name="Gravel",color=new Color(.46f,.43f,.36f),mode=10f},new{name="Straw",color=new Color(.38f,.33f,.20f),mode=11f},new{name="Faded",color=new Color(.43f,.40f,.29f),mode=11f},new{name="Sage",color=new Color(.27f,.30f,.23f),mode=11f},new{name="Seed",color=new Color(.36f,.29f,.17f),mode=11f},new{name="Twig",color=new Color(.24f,.20f,.16f),mode=12f}}){string p=E+"Materials/WD_M_"+q.name+".mat";if(AssetDatabase.LoadAssetAtPath<Material>(p))continue;var m=new Material(shader){name="WD_M_"+q.name,enableInstancing=true};m.SetColor("_BaseColor",q.color);m.SetFloat("_AE_Mode",q.mode);m.SetFloat("_Smoothness",.1f);m.SetFloat("_Metallic",0);m.SetFloat("_Cull",q.mode==11?0:2);AssetDatabase.CreateAsset(m,p);}
 }
 static void Import(){foreach(var q in JArray.Parse(File.ReadAllText(Src+"models.json"))){string name=(string)q["name"],p=E+name+".fbx";File.Copy(Path.Combine(Path.GetTempPath(),"AfterSeconds_WildernessDetail_20261113/candidate/"+name+".fbx"),p,true);AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var im=(ModelImporter)AssetImporter.GetAtPath(p);im.importAnimation=false;im.importCameras=false;im.importLights=false;im.isReadable=false;im.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(string n in q["materials"].Values<string>())im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),n),AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/"+n+".mat"));im.SaveAndReimport();models[name]=AssetDatabase.LoadAssetAtPath<GameObject>(p);}}
 static void Bind(Transform root,string model,string kind){var proto=models[model];var sources=proto.GetComponentsInChildren<MeshFilter>().OrderBy(f=>f.name).ToArray();if(sources.Length!=3)throw new Exception(model+" LOD count");var rr=new Renderer[3];for(int i=0;i<3;i++){var go=i==0?root.gameObject:new GameObject("WildernessLOD"+i);if(i>0)go.transform.SetParent(root,false);var f=go.GetComponent<MeshFilter>();if(!f)f=go.AddComponent<MeshFilter>();var r=go.GetComponent<MeshRenderer>();if(!r)r=go.AddComponent<MeshRenderer>();f.sharedMesh=sources[i].sharedMesh;r.sharedMaterials=sources[i].GetComponent<Renderer>().sharedMaterials;r.shadowCastingMode=kind=="Grass"||kind=="Pebbles"?ShadowCastingMode.Off:ShadowCastingMode.On;r.receiveShadows=true;rr[i]=r;Record(f);Record(r);}
 var c=root.GetComponent<MeshCollider>();if(c){c.sharedMesh=sources[1].sharedMesh;Record(c);}var lod=root.GetComponent<LODGroup>();if(!lod)lod=root.gameObject.AddComponent<LODGroup>();var levels=kind=="Rock"?new[]{.055f,.018f,.002f}:kind=="Pebbles"?new[]{.14f,.065f,.018f}:new[]{.065f,.027f,.0045f};lod.fadeMode=LODFadeMode.CrossFade;lod.animateCrossFading=false;lod.SetLODs(Enumerable.Range(0,3).Select(i=>new LOD(levels[i],new[]{rr[i]}){fadeTransitionWidth=.15f}).ToArray());lod.RecalculateBounds();Record(lod);changes.Add(new{path=AnimationUtility.CalculateTransformPath(root,null),model,kind,colliderChanged=c!=null});}
 static void TerrainSurface(){var layers=new TerrainLayer[4];for(int i=0;i<4;i++){var l=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<TerrainLayer>(E+"FW_Dry"+(i==1?1:0)+".terrainlayer"));l.name=new[]{"WD_Earth","WD_Gravel","WD_PaleDust","WD_CompactedSoil"}[i];float tile=new[]{8f,2.4f,12f,5f}[i];l.tileSize=new Vector2(tile,tile);l.normalScale=new[]{.50f,.55f,.18f,.26f}[i];l.smoothness=.015f;l.metallic=0;l.diffuseRemapMin=Vector4.zero;l.diffuseRemapMax=new[]{new Vector4(1.68f,1.60f,1.42f,1),new Vector4(1.72f,1.62f,1.43f,1),new Vector4(2.12f,2.0f,1.78f,1),new Vector4(1.82f,1.72f,1.51f,1)}[i];AssetDatabase.CreateAsset(l,E+l.name+".terrainlayer");layers[i]=l;}
 foreach(var t in new[]{near,mid,GameObject.Find("FW_DistantHorizonTerrain").GetComponent<Terrain>()}){var d=t.terrainData;int n=d.alphamapResolution;var old=d.GetAlphamaps(0,0,n,n);if(d.terrainLayers.Length!=3)throw new Exception("Unexpected terrain layers");d.terrainLayers=d.terrainLayers.Concat(layers).ToArray();var alpha=new float[n,n,7];for(int z=0;z<n;z++)for(int x=0;x<n;x++){float wx=t.transform.position.x+x*d.size.x/(n-1),wz=t.transform.position.z+z*d.size.z/(n-1);float mask=S(61,85,-wx);for(int k=0;k<3;k++)alpha[z,x,k]=old[z,x,k]*(1-mask);float jitter=(Mathf.PerlinNoise(wx*.21f+12,wz*.21f+31)-.5f)*1.4f;float distance=Mathf.Abs(wz-RoadZ(wx)+jitter);float path=1-S(2.0f,4.7f,distance);float n1=Mathf.PerlinNoise(wx*.044f+12,wz*.044f+21),n2=Mathf.PerlinNoise(wx*.23f+42,wz*.23f+81);float gravel=.10f+S(.45f,.72f,n2)*.4f;float dust=S(.32f,.69f,n1)*.58f;float soil=path*(.56f+.2f*n2);float earth=Mathf.Max(.08f,1-gravel-dust-soil);float total=earth+gravel+dust+soil;alpha[z,x,3]=earth/total*mask;alpha[z,x,4]=gravel/total*mask;alpha[z,x,5]=dust/total*mask;alpha[z,x,6]=soil/total*mask;}d.SetAlphamaps(0,0,alpha);t.basemapDistance=t==near?380:t==mid?1300:2000;t.heightmapPixelError=t==near?5:t==mid?6:8;EditorUtility.SetDirty(d);t.Flush();}
 }
 static void Horizon(){var t=GameObject.Find("FW_DistantHorizonTerrain").GetComponent<Terrain>();var d=t.terrainData;int n=d.heightmapResolution;var h=d.GetHeights(0,0,n,n);for(int z=0;z<n;z++)for(int x=0;x<n;x++){float wx=t.transform.position.x+x*d.size.x/(n-1),wz=t.transform.position.z+z*d.size.z/(n-1);float mask=S(770,1030,-wx);if(mask<=0)continue;float center=-50+.015f*(wx+800);float side=S(55,330,Mathf.Abs(wz-center));float variation=.72f+.28f*Mathf.PerlinNoise(wz*.013f+33,wx*.006f+18);float a=Mathf.Exp(-Mathf.Pow((wx+1050+Mathf.Sin(wz*.007f)*80)/165,2))*24;float b=Mathf.Exp(-Mathf.Pow((wx+1640+Mathf.Cos(wz*.005f)*120)/260,2))*49;float c=Mathf.Exp(-Mathf.Pow((wx+2420+Mathf.Sin(wz*.004f)*210)/340,2))*78;float rise=(a+b+c)*Mathf.Lerp(.42f,1,side)*variation;h[z,x]=Mathf.Clamp01(h[z,x]+rise/d.size.y*mask);}d.SetHeights(0,0,h);EditorUtility.SetDirty(d);t.Flush();var camera=Camera.main;camera.farClipPlane=4500;Record(camera);}
 public static object Run(){Check();if(GameObject.Find("WildernessGroundDetail"))throw new Exception("Already applied");if(!File.Exists(Out+"before_transforms.json"))throw new Exception("Baseline required");var s=SceneManager.GetActiveScene();near=GameObject.Find("AE_OvergrownFactoryTerrain").GetComponent<Terrain>();mid=GameObject.Find("FW_WildernessTerrain").GetComponent<Terrain>();Materials();Import();TerrainSurface();Horizon();var root=GameObject.Find("WildernessEnding").transform;var props=root.Find("DryScrubAndStone").Cast<Transform>().ToArray();int index=0;foreach(var t in props){string kind=t.name.Contains("Rock")?"Rock":t.name.Contains("Shrub")?"Shrub":"Grass";int count=kind=="Grass"?4:3;string name="WD_"+kind+(char)('A'+index++%count);Bind(t,name,kind);}
 var group=new GameObject("WildernessGroundDetail").transform;group.SetParent(root,false);var rng=new System.Random(131149);int added=0;for(int patch=0;patch<94;patch++){float x=-73-(float)rng.NextDouble()*570;float side=patch%2==0?1:-1;float z=RoadZ(x)+side*(4.8f+(float)rng.NextDouble()*21);int count=3+rng.Next(5);for(int j=0;j<count;j++){float px=x+((float)rng.NextDouble()-.5f)*4.3f,pz=z+((float)rng.NextDouble()-.5f)*3;if(Mathf.Abs(pz-RoadZ(px))<3.6f)continue;bool stone=j%3==0;string kind=stone?"Pebbles":"Grass",model=stone?"WD_StonePatch"+(char)('A'+patch%2):"WD_Grass"+(char)('A'+rng.Next(4));var g=new GameObject("WD_"+kind+"_"+(added++).ToString("000"));g.transform.SetParent(group,false);g.transform.position=new Vector3(px,Height(px,pz),pz);g.transform.rotation=Quaternion.Euler(0,(float)rng.NextDouble()*360,0);g.transform.localScale=Vector3.one*(stone?.8f+(float)rng.NextDouble()*.8f:.65f+(float)rng.NextDouble()*.8f);Bind(g.transform,model,kind);}}
 Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(Out+"placements.json",JsonConvert.SerializeObject(changes,Formatting.Indented));var result=new{models=models.Count,replaced=props.Length,added,farClip=Camera.main.farClipPlane,saved=true};File.WriteAllText(Out+"apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
